<span class="line">      <span class="token function">drawDashedLine</span><span class="token punctuation">(</span>g<span class="token punctuation">,</span> x<span class="token punctuation">,</span> y <span class="token operator">+</span> h<span class="token punctuation">,</span> x<span class="token punctuation">,</span> y<span class="token punctuation">,</span> dash<span class="token punctuation">,</span> gap<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
